CREATE POLICY voucher_art_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='voucher-artwork' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY voucher_art_add ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='voucher-artwork' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY voucher_art_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='voucher-artwork' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE FUNCTION public.create_voucher_batch(b jsonb, items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; r jsonb; BEGIN SELECT id INTO bid FROM voucher_batches WHERE request_key=(b->>'request_key')::uuid AND owner_id=(b->>'owner_id')::uuid; IF bid IS NOT NULL THEN RETURN bid; END IF; INSERT INTO voucher_batches(owner_id,router_id,source,package_name,package_snapshot,label,requested,mode,request_key) VALUES((b->>'owner_id')::uuid,(b->>'router_id')::uuid,b->>'source',b->>'package_name',b->'package_snapshot',b->>'label',(b->>'requested')::integer,b->>'mode',(b->>'request_key')::uuid) RETURNING id INTO bid; FOR r IN SELECT value FROM jsonb_array_elements(items) LOOP INSERT INTO voucher_items(id,batch_id,owner_id,router_id,source,name,ordinal) VALUES((r->>'id')::uuid,bid,(b->>'owner_id')::uuid,(b->>'router_id')::uuid,b->>'source',r->>'name',(r->>'ordinal')::integer); INSERT INTO voucher_secrets(item_id,ciphertext) VALUES((r->>'id')::uuid,r->>'ciphertext'); END LOOP; RETURN bid; END $$;
REVOKE ALL ON FUNCTION public.create_voucher_batch(jsonb,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.create_voucher_batch(jsonb,jsonb) TO service_role;
CREATE FUNCTION public.purge_voucher_secrets(bid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM voucher_secrets WHERE item_id IN (SELECT id FROM voucher_items WHERE batch_id=bid); UPDATE voucher_items SET secret_valid=false WHERE batch_id=bid; END $$;
REVOKE ALL ON FUNCTION public.purge_voucher_secrets(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.purge_voucher_secrets(uuid) TO service_role;